import subprocess
import os
import shutil
from glob import glob

def task_func(src_folder, dst_folder):
    if not os.path.isdir(src_folder) or not os.path.isdir(dst_folder):
        return {'success': False, 'message': 'Source or destination folder does not exist', 'failed_files': []}
    failed_files = []
    for file_path in glob(os.path.join(src_folder, '*')):
        if os.path.isfile(file_path):
            try:
                result = subprocess.run(f'gzip -f "{file_path}" &', shell=True, capture_output=True)
                if result.returncode != 0:
                    failed_files.append(os.path.basename(file_path))
                else:
                    gz_file = file_path + '.gz'
                    shutil.move(gz_file, dst_folder)
            except Exception:
                failed_files.append(os.path.basename(file_path))
    if not failed_files:
        return {'success': True, 'message': 'All files compressed and moved successfully', 'failed_files': failed_files}
    else:
        return {'success': False, 'message': 'Some files failed to compress or move', 'failed_files': failed_files}
